success.beforeFullFileContent:
import React from "react";
import { createRoot } from "react-dom/client";
import "./styles.css";

const photos = [
  "https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1200&q=85",
  "https://images.unsplash.com/photo-1551107696-a4b0c5a0d9a2?auto=format&fit=crop&w=1200&q=85",
  "https://images.unsplash.com/photo-1552346154-21d32810aba3?auto=format&fit=crop&w=1200&q=85",
];

const sizes = [
  { value: "7", available: true },
  { value: "8", available: true },
  { value: "9", available: false },
  { value: "10", available: true },
  { value: "11", available: true },
];

const questions = [
  ["Is the Trail Runner 2 waterproof?", "The Trail Runner 2 has a water-resistant upper for light rain and damp trails."],
  ["How does the shoe fit?", "It fits true to size with a comfortably secure fit for trail running."],
  ["Can I return my shoes?", "Yes. Unworn shoes can be returned within 30 days of delivery."],
];

function App() {
  const [photoIndex, setPhotoIndex] = React.useState(0);
  const [color, setColor] = React.useState("Blue");
  const [size, setSize] = React.useState("");
  const [sizeOpen, setSizeOpen] = React.useState(false);
  const [guideOpen, setGuideOpen] = React.useState(false);
  const [footLength, setFootLength] = React.useState("");
  const [unit, setUnit] = React.useState("US");
  const [quantity, setQuantity] = React.useState(1);
  const [wishlist, setWishlist] = React.useState(false);
  const [cartCount, setCartCount] = React.useState(0);
  const [alert, setAlert] = React.useState("");
  const [activeTab, setActiveTab] = React.useState("Details");
  const [openQuestion, setOpenQuestion] = React.useState(null);

  const changeQuantity = (amount) => {
    setQuantity((current) => Math.max(1, current + amount));
  };

  const calculatedSize = footLength
    ? unit === "EU"
      ? Number(footLength) >= 27
        ? "EU 43"
        : Number(footLength) >= 26
          ? "EU 42"
          : "EU 40"
      : Number(footLength) >= 27
        ? "US 10"
        : Number(footLength) >= 26
          ? "US 9"
          : "US 7";

  const addToCart = () => {
    if (!size) {
      setAlert("Please choose a size before adding this shoe to your cart.");
      return;
    }
    setCartCount((count) => count + Number(quantity));
    setAlert(`${quantity} Trail Runner 2 added to cart.`);
  };

  return (
    <div className="site-shell">
      <header className="site-header">
        <a className="logo" href="/">Stride</a>
        <nav className="main-nav" aria-label="Main menu">
          <a href="#men">Men</a>
          <a href="#women">Women</a>
          <a href="#kids">Kids</a>
        </nav>
        <a className="cart-link" href="#cart" aria-label={`Cart, ${cartCount} items`}>
          Cart <span>{cartCount}</span>
        </a>
      </header>

      <main>
        <nav className="breadcrumbs" aria-label="Breadcrumb">
          <a href="#shop">Shop</a><span>/</span>
          <a href="#trail">Trail</a><span>/</span>
          <span aria-current="page">Trail Runner 2</span>
        </nav>

        <section className="product-layout" aria-labelledby="product-title">
          <div className="gallery">
            <div className="photo-frame">
              <img src={photos[photoIndex]} alt={`Trail Runner 2 in ${color.toLowerCase()}`} />
              <button className="gallery-button previous" type="button" aria-label="Previous photo"
                onClick={() => setPhotoIndex((photoIndex - 1 + photos.length) % photos.length)}>‹</button>
              <button className="gallery-button next" type="button" aria-label="Next photo"
                onClick={() => setPhotoIndex((photoIndex + 1) % photos.length)}>›</button>
            </div>
            <div className="photo-count" aria-live="polite">{photoIndex + 1} / {photos.length}</div>
          </div>

          <div className="product-info">
            <p className="eyebrow">New arrival · Trail collection</p>
            <div className="title-row">
              <div>
                <h1 id="product-title">Trail Runner 2</h1>
                <p className="subtitle">Built for the path less travelled.</p>
              </div>
              <button className={`wishlist ${wishlist ? "saved" : ""}`} type="button"
                aria-label={wishlist ? "Remove from wishlist" : "Add to wishlist"}
                aria-pressed={wishlist} onClick={() => setWishlist(!wishlist)}>
                {wishlist ? "♥" : "♡"}
              </button>
            </div>

            <div className="price-row">
              <strong>$145.00</strong>
              <span className="price-help">
                <button type="button" aria-label="Price information">i</button>
                <span className="tooltip" role="tooltip">Taxes included in the price.</span>
              </span>
            </div>

            <div className="choice-group">
              <div className="label-row"><span>Color</span><span className="muted">{color}</span></div>
              <div className="swatches" role="radiogroup" aria-label="Color">
                {["Blue", "Black", "Grey"].map((option) => (
                  <label className="swatch-label" key={option}>
                    <input type="radio" name="color" value={option} checked={color === option}
                      onChange={() => setColor(option)} />
                    <span className={`swatch ${option.toLowerCase()}`} aria-hidden="true" />
                    <span>{option}</span>
                  </label>
                ))}
              </div>
            </div>

            <div className="size-heading">
              <span>Size</span>
              <button type="button" className="text-button" aria-label="Size guide" onClick={() => setGuideOpen(true)}>Size guide</button>
            </div>
            <div className="size-picker">
              <button className="size-current" type="button"
                aria-label={size ? `Current size ${size}` : "Select size"} onClick={() => setSizeOpen(!sizeOpen)}>
                {size ? `Size ${size}` : "Select size"} <span>⌄</span>
              </button>
              {sizeOpen && (
                <div className="size-list" role="listbox" aria-label="Size options">
                  {sizes.map((item) => (
                    <button role="option" type="button" key={item.value} disabled={!item.available}
                      aria-selected={size === item.value}
                      onClick={() => { if (item.available) { setSize(item.value); setSizeOpen(false); } }}>
                      {item.value} {!item.available && <span>Sold out</span>}
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="purchase-row">
              <div className="quantity">
                <button type="button" aria-label="Decrease quantity" onClick={() => changeQuantity(-1)}>−</button>
                <input aria-label="Quantity" type="number" min="1" value={quantity}
                  onChange={(event) => setQuantity(Math.max(1, Number(event.target.value) || 1))} />
                <button type="button" aria-label="Increase quantity" onClick={() => changeQuantity(1)}>+</button>
              </div>
              <button className="add-button" type="button" onClick={addToCart}>Add to cart</button>
            </div>
            {alert && <div className="alert" role="alert">{alert}</div>}
            <p className="shipping-note">Free shipping and returns on every order.</p>
          </div>
        </section>

        <section className="details-section" aria-label="Product information">
          <div className="tabs" role="tablist" aria-label="Product information tabs">
            {["Details", "Reviews", "Shipping"].map((tab) => (
              <button key={tab} role="tab" type="button" aria-selected={activeTab === tab}
                onClick={() => setActiveTab(tab)}>{tab}</button>
            ))}
          </div>
          <div className="tabpanel" role="tabpanel">
            {activeTab === "Details" && <p>Trail Runner 2 is a lightweight, responsive trail shoe with a grippy outsole and breathable mesh upper, ready for everyday adventures.</p>}
            {activeTab === "Reviews" && <p><strong>4.8 out of 5</strong> · Loved by runners. “Comfortable from the first mile and confident on rocky ground.”</p>}
            {activeTab === "Shipping" && <p>Enjoy free standard shipping and easy 30-day returns. Orders leave our warehouse within one business day.</p>}
          </div>
        </section>

        <section className="questions" aria-labelledby="questions-title">
          <p className="eyebrow">Need to know</p>
          <h2 id="questions-title">Common questions</h2>
          {questions.map(([question, answer], index) => (
