@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap");

:root {
  --ink: #172321;
  --muted: #697571;
  --line: #dce3df;
  --cream: #f5f4ef;
  --green: #123d35;
  --orange: #ef693e;
}

* { box-sizing: border-box; }
body { margin: 0; color: var(--ink); background: #fbfbf8; font-family: "DM Sans", sans-serif; }
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button { cursor: pointer; }
.site-shell { min-height: 100vh; }
.site-header { height: 82px; border-bottom: 1px solid var(--line); display: flex; align-items: center; padding: 0 clamp(24px, 6vw, 90px); gap: 72px; background: #fbfbf8; }
.logo, .footer-logo { font: 700 28px "Playfair Display", serif; letter-spacing: -.04em; }
.main-nav { display: flex; gap: 34px; font-size: 13px; font-weight: 600; }
.main-nav a:hover, .site-footer a:hover { color: var(--orange); }
.cart-link { margin-left: auto; font-size: 13px; font-weight: 600; }
.cart-link span { display: inline-grid; place-items: center; width: 23px; height: 23px; margin-left: 7px; border-radius: 50%; color: white; background: var(--green); font-size: 11px; }
main { max-width: 1180px; margin: auto; padding: 29px 32px 100px; }
.breadcrumbs { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 12px; margin-bottom: 48px; }
.breadcrumbs a { color: var(--ink); border-bottom: 1px solid #acb9b3; }
.product-layout { display: grid; grid-template-columns: minmax(400px, 1.1fr) minmax(360px, .9fr); gap: clamp(45px, 8vw, 125px); align-items: start; }
.gallery { text-align: center; }
.photo-frame { position: relative; background: var(--cream); aspect-ratio: 1 / 1.08; display: grid; place-items: center; overflow: hidden; }
.photo-frame img { width: 100%; height: 100%; object-fit: cover; mix-blend-mode: multiply; transition: opacity .2s; }
.gallery-button { position: absolute; top: 50%; transform: translateY(-50%); width: 42px; height: 42px; border: 1px solid var(--line); border-radius: 50%; color: var(--ink); background: rgba(255,255,255,.9); font-size: 28px; line-height: 1; }
.gallery-button:hover { background: white; }
.gallery-button.previous { left: 18px; }
.gallery-button.next { right: 18px; }
.photo-count { padding-top: 15px; color: var(--muted); font-size: 12px; }
.eyebrow { color: var(--orange); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; font-weight: 700; margin: 2px 0 14px; }
h1, h2 { font-family: "Playfair Display", serif; }
h1 { margin: 0; font-size: clamp(38px, 4vw, 58px); letter-spacing: -.045em; line-height: 1; }
.subtitle { color: var(--muted); font-size: 14px; margin: 13px 0 0; }
.title-row { display: flex; justify-content: space-between; align-items: start; }
.wishlist { width: 43px; height: 43px; border: 1px solid var(--line); border-radius: 50%; color: var(--green); background: transparent; font-size: 25px; line-height: 1; }
.wishlist.saved { color: var(--orange); background: #fff0e9; border-color: #f4b8a2; }
.price-row { display: flex; align-items: center; gap: 10px; margin: 36px 0 35px; }
.price-row strong { font-size: 20px; }
.price-help { position: relative; }
.price-help button { display: grid; place-items: center; width: 17px; height: 17px; border: 1px solid var(--muted); border-radius: 50%; color: var(--muted); background: transparent; font-size: 11px; }
.tooltip { display: none; position: absolute; left: 50%; bottom: 27px; transform: translateX(-50%); padding: 8px 11px; width: max-content; border-radius: 4px; color: white; background: var(--ink); font-size: 11px; z-index: 2; }
.price-help:hover .tooltip, .price-help:focus-within .tooltip { display: block; }
.choice-group { border-top: 1px solid var(--line); padding-top: 22px; }
.label-row, .size-heading { display: flex; justify-content: space-between; align-items: center; font-size: 13px; font-weight: 600; }
.muted { color: var(--muted); font-weight: 400; }
.swatches { display: flex; gap: 25px; margin: 17px 0 31px; }
.swatch-label { display: flex; align-items: center; gap: 8px; cursor: pointer; font-size: 12px; }
.swatch-label input { position: absolute; opacity: 0; }
.swatch { width: 21px; height: 21px; border: 2px solid #fff; border-radius: 50%; outline: 1px solid transparent; }
.swatch-label input:checked + .swatch { outline-color: var(--ink); }
.swatch.blue { background: #45758b; }.swatch.black { background: #1d2524; }.swatch.grey { background: #a7aaa3; }
.text-button { border: 0; border-bottom: 1px solid var(--ink); background: transparent; padding: 0; color: var(--ink); font-size: 12px; }
.size-picker { position: relative; margin-top: 12px; }
.size-current { width: 100%; display: flex; justify-content: space-between; padding: 15px; border: 1px solid var(--line); color: var(--ink); background: white; text-align: left; font-size: 13px; }
.size-list { position: absolute; left: 0; right: 0; top: 100%; z-index: 3; padding: 7px; border: 1px solid var(--line); background: white; box-shadow: 0 12px 25px #173b3215; }
.size-list button { width: 100%; display: flex; justify-content: space-between; padding: 11px; border: 0; background: transparent; text-align: left; }
.size-list button:hover:not(:disabled) { background: var(--cream); }.size-list button:disabled { color: #a4ada8; text-decoration: line-through; cursor: not-allowed; }
.size-list button span { font-size: 11px; text-transform: uppercase; }
.purchase-row { display: flex; gap: 11px; margin-top: 25px; }
.quantity { display: flex; align-items: center; border: 1px solid var(--line); background: white; }
.quantity button { border: 0; width: 32px; height: 48px; background: transparent; font-size: 20px; color: var(--muted); }
.quantity input { width: 30px; border: 0; outline: none; text-align: center; font-size: 13px; appearance: textfield; }
.quantity input::-webkit-inner-spin-button { appearance: none; }
.add-button { flex: 1; border: 0; color: white; background: var(--green); font-weight: 600; }.add-button:hover { background: #1b5549; }
.alert { margin-top: 13px; padding: 10px 12px; border-radius: 3px; color: #8e351d; background: #fff0e9; font-size: 12px; }
.shipping-note { color: var(--muted); font-size: 11px; margin-top: 18px; }
.details-section { margin-top: 110px; border-top: 1px solid var(--line); }
.tabs { display: flex; gap: 36px; border-bottom: 1px solid var(--line); }
.tabs button { position: relative; padding: 18px 0 15px; border: 0; color: var(--muted); background: transparent; font-size: 13px; }
.tabs button[aria-selected="true"] { color: var(--ink); font-weight: 600; }.tabs button[aria-selected="true"]::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; background: var(--orange); }
.tabpanel { min-height: 72px; padding: 24px 0; color: var(--muted); font-size: 13px; line-height: 1.7; max-width: 720px; }
.questions { max-width: 780px; margin: 65px auto 0; }.questions h2 { margin: 0 0 25px; font-size: 35px; }
.question { border-top: 1px solid var(--line); }.question:last-child { border-bottom: 1px solid var(--line); }
.question > button { width: 100%; display: flex; justify-content: space-between; padding: 19px 0; border: 0; color: var(--ink); background: transparent; text-align: left; font-size: 13px; font-weight: 600; }
.question > button span { color: var(--orange); font-size: 20px; font-weight: 400; }.answer { color: var(--muted); font-size: 12px; line-height: 1.6; }.answer p { margin: -3px 35px 20px 0; }
.site-footer { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 35px; padding: 65px max(32px, calc((100vw - 1116px) / 2)); color: white; background: var(--green); }
.footer-logo { color: white; }.site-footer p { color: #b1c3bd; font-size: 12px; }.site-footer h3 { margin: 0 0 17px; color: #b1c3bd; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }.site-footer a:not(.footer-logo) { display: block; margin-bottom: 10px; font-size: 12px; }
.modal-backdrop { position: fixed; inset: 0; z-index: 10; display: grid; place-items: center; padding: 20px; background: #17232199; }.size-guide { position: relative; width: min(470px, 100%); padding: 38px; background: #fbfbf8; box-shadow: 0 20px 60px #0003; }.size-guide h2 { margin: 0 0 25px; font-size: 34px; }.close-button { position: absolute; top: 14px; right: 15px; border: 0; background: transparent; font-size: 26px; }.size-guide label[for], .size-guide input[type="number"] { display: block; }.size-guide label[for] { margin-bottom: 8px; font-size: 12px; font-weight: 600; }.size-guide input[type="number"] { width: 100%; padding: 12px; border: 1px solid var(--line); background: white; }.unit-choice { display: flex; gap: 20px; margin: 18px 0; font-size: 12px; }.calculated { padding: 12px; background: #edf3ef; font-size: 13px; }.size-guide table { width: 100%; margin-top: 20px; border-collapse: collapse; font-size: 12px; text-align: left; }.size-guide caption { margin-bottom: 8px; color: var(--muted); text-align: left; }.size-guide th, .size-guide td { padding: 9px; border-bottom: 1px solid var(--line); }
@media (max-width: 750px) {
  .site-header { height: 68px; gap: 25px; padding: 0 20px; }.main-nav { gap: 15px; }.logo { font-size: 24px; }
  main { padding: 25px 20px 65px; }.breadcrumbs { margin-bottom: 30px; }.product-layout { grid-template-columns: 1fr; gap: 40px; }.gallery { max-width: 550px; width: 100%; margin: auto; }
  .details-section { margin-top: 70px; }.site-footer { grid-template-columns: 1fr 1fr; padding: 45px 20px; }.site-footer > div:first-child { grid-column: 1 / -1; }
}

