.size-list button span { font-size: 11px; text-transform: uppercase; }
.purchase-row { display: flex; gap: 11px; margin-top: 25px; }
.quantity { display: flex; align-items: center; border: 1px solid var(--line); background: white; }
.quantity button { border: 0; width: 32px; height: 48px; background: transparent; font-size: 20px; color: var(--muted); }
.quantity input { width: 30px; border: 0; outline: none; text-align: center; font-size: 13px; appearance: textfield; }
.quantity input::-webkit-inner-spin-button { appearance: none; }
.add-button { flex: 1; border: 0; color: white; background: var(--green); font-weight: 600; }.add-button:hover { background: #1b5549; }
.alert { margin-top: 13px; padding: 10px 12px; border-radius: 3px; color: #8e351d; background: #fff0e9; font-size: 12px; }
.shipping-note { color: var(--muted); font-size: 11px; margin-top: 18px; }
.details-section { margin-top: 110px; border-top: 1px solid var(--line); }
.tabs { display: flex; gap: 36px; border-bottom: 1px solid var(--line); }
.tabs button { position: relative; padding: 18px 0 15px; border: 0; color: var(--muted); background: transparent; font-size: 13px; }
.tabs button[aria-selected="true"] { color: var(--ink); font-weight: 600; }.tabs button[aria-selected="true"]::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; background: var(--orange); }
.tabpanel { min-height: 72px; padding: 24px 0; color: var(--muted); font-size: 13px; line-height: 1.7; max-width: 720px; }
.questions { max-width: 780px; margin: 65px auto 0; }.questions h2 { margin: 0 0 25px; font-size: 35px; }
.question { border-top: 1px solid var(--line); }.question:last-child { border-bottom: 1px solid var(--line); }
.question > button { width: 100%; display: flex; justify-content: space-between; padding: 19px 0; border: 0; color: var(--ink); background: transparent; text-align: left; font-size: 13px; font-weight: 600; }
.question > button span { color: var(--orange); font-size: 20px; font-weight: 400; }.answer { color: var(--muted); font-size: 12px; line-height: 1.6; }.answer p { margin: -3px 35px 20px 0; }
.site-footer { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 35px; padding: 65px max(32px, calc((100vw - 1116px) / 2)); color: white; background: var(--green); }
.footer-logo { color: white; }.site-footer p { color: #b1c3bd; font-size: 12px; }.site-footer h3 { margin: 0 0 17px; color: #b1c3bd; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }.site-footer a:not(.footer-logo) { display: block; margin-bottom: 10px; font-size: 12px; }
.modal-backdrop { position: fixed; inset: 0; z-index: 10; display: grid; place-items: center; padding: 20px; background: #17232199; }.size-guide { position: relative; width: min(470px, 100%); padding: 38px; background: #fbfbf8; box-shadow: 0 20px 60px #0003; }.size-guide h2 { margin: 0 0 25px; font-size: 34px; }.close-button { position: absolute; top: 14px; right: 15px; border: 0; background: transparent; font-size: 26px; }.size-guide label[for], .size-guide input[type="number"] { display: block; }.size-guide label[for] { margin-bottom: 8px; font-size: 12px; font-weight: 600; }.size-guide input[type="number"] { width: 100%; padding: 12px; border: 1px solid var(--line); background: white; }.unit-choice { display: flex; gap: 20px; margin: 18px 0; font-size: 12px; }.calculated { padding: 12px; background: #edf3ef; font-size: 13px; }.size-guide table { width: 100%; margin-top: 20px; border-collapse: collapse; font-size: 12px; text-align: left; }.size-guide caption { margin-bottom: 8px; color: var(--muted); text-align: left; }.size-guide th, .size-guide td { padding: 9px; border-bottom: 1px solid var(--line); }
@media (max-width: 750px) {
  .site-header { height: 68px; gap: 25px; padding: 0 20px; }.main-nav { gap: 15px; }.logo { font-size: 24px; }
  main { padding: 25px 20px 65px; }.breadcrumbs { margin-bottom: 30px; }.product-layout { grid-template-columns: 1fr; gap: 40px; }.gallery { max-width: 550px; width: 100%; margin: auto; }
  .details-section { margin-top: 70px; }.site-footer { grid-template-columns: 1fr 1fr; padding: 45px 20px; }.site-footer > div:first-child { grid-column: 1 / -1; }
}
